    auctionSentences: [
      { sentence:"Watching movies in the target language builds listening skills over time.", isCorrect:true, explanation:"The gerund subject 'Watching' is singular, so it correctly takes the singular verb 'builds'." },
      { sentence:"She don't understand the grammar rule about irregular verbs.", isCorrect:false, explanation:"The subject 'She' is third-person singular, so the verb must be 'doesn't', not 'don't'." },
      { sentence:"It is essential to review new vocabulary regularly.", isCorrect:true, explanation:"'It is essential to + infinitive' is the correct structure." },
      { sentence:"He is interested in learn Spanish for his upcoming trip to Mexico.", isCorrect:false, explanation:"After the preposition 'in', a gerund is needed: 'learning', not the base form 'learn'." },
      { sentence:"Native speakers often speak more quickly than textbooks suggest.", isCorrect:true, explanation:"'More quickly' is the correct adverb comparative form used to modify the verb 'speak'." },
      { sentence:"My pronunciation is getting more good since I started taking lessons.", isCorrect:false, explanation:"'Good' has an irregular comparative, 'better'; 'more good' is not correct." },
      { sentence:"One of the biggest challenges for learners is remembering irregular verb forms.", isCorrect:true, explanation:"After 'one of the biggest', a plural noun ('challenges') is required, and this is used correctly." },
      { sentence:"One of the main benefit of bilingualism is improved memory.", isCorrect:false, explanation:"After 'one of the main', the noun must be plural: 'benefits', not 'benefit'." },
      { sentence:"Immersion programs allow students to practise the language in real situations.", isCorrect:true, explanation:"'Allow + object + to + infinitive' is the correct pattern." },
      { sentence:"The teacher made the students to repeat the phrase five times.", isCorrect:false, explanation:"The causative verb 'make' is followed by the bare infinitive, so it should be 'repeat', not 'to repeat'." },
    ],
